          + '<div class="ob-erg-group-total">' + esc(sumLabel) + '</div>'
          + '<div class="ob-erg-group-count">' + esc(countLabel) + '</div>'
          + '<div class="ob-erg-group-badge">' + esc(mode) + '</div>'
          + '</div></div>');
      }

      function doCollapse($h) {
        var lv = parseInt($h.attr("data-group-level"), 10);
        collapsed_groups[$h.attr("data-chain-key")] = true;
