        while ($n.length) { if ($n.hasClass("ob-erg-group-header") && parseInt($n.attr("data-group-level"), 10) <= lv) break; $n.addClass("ob-erg-hidden-by-collapse"); $n = $n.next(); }
      }
      function doExpand($h) {
        var lv = parseInt($h.attr("data-group-level"), 10);
        delete collapsed_groups[$h.attr("data-chain-key")];
        $h.attr("data-collapsed", "0").find(".ob-erg-group-toggle").html("&#9660;");
        var $n = $h.next();
        while ($n.length) {
          if ($n.hasClass("ob-erg-group-header")) {
            var nl = parseInt($n.attr("data-group-level"), 10); if (nl <= lv) break;
            $n.removeClass("ob-erg-hidden-by-collapse");
            if ($n.attr("data-collapsed") === "1") { var $sb = $n.next(); while ($sb.length) { if ($sb.hasClass("ob-erg-group-header") && parseInt($sb.attr("data-group-level"), 10) <= nl) break; $sb.addClass("ob-erg-hidden-by-collapse"); $sb = $sb.next(); } }
          } else { $n.removeClass("ob-erg-hidden-by-collapse"); }
          $n = $n.next();
        }
        listview.$result.find(".ob-erg-group-header[data-collapsed='1']").each(function () { doCollapse($(this)); });
      }
      function bindEv() { listview.$result.find(".ob-erg-group-header").off("click.oberg").on("click.oberg", function (e) { e.stopPropagation(); $(this).attr("data-collapsed") === "1" ? doExpand($(this)) : doCollapse($(this)); }); }

      function applyGrouping() {
        if (is_rendering || !listview.$result) return;
