      }
      function doExpand($h) {
        var lv = parseInt($h.attr("data-group-level"), 10);
        delete collapsed_groups[$h.attr("data-chain-key")];
        $h.attr("data-collapsed", "0").find(".ob-erg-group-toggle").html("&#9660;");
        var $n = $h.next();
        while ($n.length) {
          if ($n.hasClass("ob-erg-group-header")) {
            var nl = parseInt($n.attr("data-group-level"), 10); if (nl <= lv) break;
            $n.removeClass("ob-erg-hidden-by-collapse");
            if ($n.attr("data-collapsed") === "1") { var $sb = $n.next(); while ($sb.length) { if ($sb.hasClass("ob-erg-group-header") && parseInt($sb.attr("data-group-level"), 10) <= nl) break; $sb.addClass("ob-erg-hidden-by-collapse"); $sb = $sb.next(); } }
          } else { $n.removeClass("ob-erg-hidden-by-collapse"); }
          $n = $n.next();
        }
        listview.$result.find(".ob-erg-group-header[data-collapsed='1']").each(function () { doCollapse($(this)); });
      }
      function bindEv() { listview.$result.find(".ob-erg-group-header").off("click.oberg").on("click.oberg", function (e) { e.stopPropagation(); $(this).attr("data-collapsed") === "1" ? doExpand($(this)) : doCollapse($(this)); }); }

      function applyGrouping() {
        if (is_rendering || !listview.$result) return;
        if (!selected_groups.length) { rmv(); return; }
        is_rendering = true;
        try {
          rmv();
          var rs = [];
          getRows().each(function () {
            var $r = $(this), n = getDN($r);
            if (!n) return;
            var d = getDoc(n), dObj = pd(d ? d[DATE_FIELD] : null), amt = d ? flt(d[AMOUNT_FIELD]) : 0;
            rs.push({ $r: $r, n: n, doc: d || {}, dObj: dObj, ts: dObj ? dObj.getTime() : 0, amt: amt });
          });
          rs.sort(function (a, b) { return a.ts !== b.ts ? a.ts - b.ts : a.n.localeCompare(b.n); });
          if (rs.length) { var $p = rs[0].$r.parent(); rs.forEach(function (r) { $p.append(r.$r); }); }

          var countMap = {}, sumMap = {};
          rs.forEach(function (item) {
            var chain = selected_groups.map(function (mode) { var g = gv(item.doc, item.dObj, mode); return { mode: mode, key: String(g.key), label: g.label }; });
            chain.forEach(function (g, idx) {
              var ck = chain.slice(0, idx + 1).map(function (x) { return x.mode + ":" + x.key; }).join("||");
              countMap[ck] = (countMap[ck] || 0) + 1;
              sumMap[ck] = (sumMap[ck] || 0) + item.amt;
            });
          });

          var pk = [], pt = null;
          rs.forEach(function (item) {
            var chain = selected_groups.map(function (mode) { var g = gv(item.doc, item.dObj, mode); return { mode: mode, key: String(g.key), label: g.label }; });
            if (!chain.length) return;
            var tk = chain[0].mode + ":" + chain[0].key;
            chain.forEach(function (g, idx) {
              var lv = idx + 1, ck = chain.slice(0, lv).map(function (x) { return x.mode + ":" + x.key; }).join("||");
              if (pk[idx] !== ck) {
                if (idx === 0 && pt !== null && tk !== pt) item.$r.before(mkSep());
                var sub = idx === 0 ? "Group by " + g.mode : chain.slice(0, idx).map(function (x) { return x.label; }).join(" / ");
                item.$r.before(mkHdr(lv, g.mode, g.label, sub, ck, countMap[ck] || 0, sumMap[ck] || 0));
                pk[idx] = ck; for (var j = idx + 1; j < pk.length; j++) pk[j] = null;
              }
            });
            pt = tk;
          });
          bindEv();
          if (!Object.keys(collapsed_groups).length) listview.$result.find(".ob-erg-group-header").each(function () { doCollapse($(this)); });
          else listview.$result.find(".ob-erg-group-header[data-collapsed='1']").each(function () { doCollapse($(this)); });
        } finally { is_rendering = false; }
      }

      function sched(d) { clearTimeout(apply_timer); apply_timer = setTimeout(function () { injectUI(); applyGrouping(); }, d || 400); }
      function updDisp() {
        if (!$widget) return;
        if (selected_groups.length) { $widget.find("#ob-erg-text").text(selected_groups.join(" + ")).removeClass("is-placeholder"); $widget.find("#ob-erg-clr").show(); }
        else { $widget.find("#ob-erg-text").text("Group By").addClass("is-placeholder"); $widget.find("#ob-erg-clr").hide(); }
      }
      function syncChk() { if (!$widget) return; $widget.find(".ob-erg-opt-check").each(function () { $(this).prop("checked", selected_groups.indexOf($(this).val()) > -1); }); }
      function buildUI() {
        var opts = GROUP_OPTIONS.map(function (o) { return '<label class="ob-erg-opt"><input type="checkbox" class="ob-erg-opt-check" value="' + o + '"><span>' + o + '</span></label>'; }).join("");
        return $('<div id="ob-erg-wrap">'
          + '<div id="ob-erg-select"><span id="ob-erg-text" class="is-placeholder">Group By</span></div>'
          + '<div id="ob-erg-chevron"><svg class="icon icon-xs" aria-hidden="true"><use href="#icon-select"></use></svg></div>'
          + '<span id="ob-erg-clr">&times;</span>'
          + '<div id="ob-erg-dd"><div class="ob-erg-dd-title">Pilih level grouping</div>' + opts
          + '<div class="ob-erg-dd-actions">'
          + '<button class="ob-erg-dd-btn" id="ob-erg-sa">All</button>'
          + '<button class="ob-erg-dd-btn" id="ob-erg-ca">Clear</button>'
          + '<button class="ob-erg-dd-btn primary" id="ob-erg-ap">Apply</button>'
          + '</div></div></div>');
      }
      function attachUI($w) {
        $w.on("click", "#ob-erg-select", function (e) { e.stopPropagation(); syncChk(); $w.find("#ob-erg-dd").toggle(); });
        $w.on("click", "#ob-erg-sa", function (e) { e.stopPropagation(); $w.find(".ob-erg-opt-check").prop("checked", true); });
        $w.on("click", "#ob-erg-ca", function (e) { e.stopPropagation(); $w.find(".ob-erg-opt-check").prop("checked", false); });
        $w.on("click", "#ob-erg-ap", function (e) {
          e.stopPropagation();
          selected_groups = GROUP_OPTIONS.filter(function (o) { return $w.find(".ob-erg-opt-check[value='" + o + "']").prop("checked"); });
          collapsed_groups = {}; updDisp(); $w.find("#ob-erg-dd").hide(); sched(300);
        });
        $w.on("click", "#ob-erg-clr", function (e) { e.stopPropagation(); selected_groups = []; collapsed_groups = {}; updDisp(); rmv(); syncChk(); });
        // Namespaced per doctype so switching List Views can't leave a
        // stale handler from a hidden, previously-visited page's copy of
        // this same widget still reacting to clicks on the live page.
        $(document).off("click.oberg_" + DOCTYPE_KEY).on("click.oberg_" + DOCTYPE_KEY, function () { if ($widget) $widget.find("#ob-erg-dd").hide(); });
        $w.on("click", "#ob-erg-dd", function (e) { e.stopPropagation(); });
      }
      function injectUI() {
        var $root = listview.page ? listview.page.wrapper : $(document);
        var $a = $root.find('[data-fieldname="' + ANCHOR_FIELD + '"].frappe-control');
        if (!$a.length) return false;
        // Already correctly attached right after the anchor on THIS page -
        // skip the remove+recreate so an open dropdown doesn't get yanked
        // shut by every single debounced render/refresh tick.
        var $existing = $root.find("#ob-erg-wrap");
        if ($existing.length && $existing.prev().is($a)) { $widget = $existing; return true; }
        $root.find("#ob-erg-wrap").remove();
        var $w = buildUI(); $a.after($w); attachUI($w); $widget = $w; updDisp(); return true;
      }
      if (!listview.__ob_erg_patched) {
        listview.__ob_erg_patched = true;
        var oR = listview.render, oRf = listview.refresh;
        listview.render = function () { var r = oR.apply(this, arguments); sched(500); return r; };
        listview.refresh = function () { var r = oRf.apply(this, arguments); sched(600); return r; };
      }
      frappe.after_ajax(function () {
        if (!injectUI()) { var n = 0; var iv = setInterval(function () { n++; if (injectUI() || n > 20) clearInterval(iv); }, 200); }
        sched(700);
      });
    },
  });
})();

// ═══════════════════════════════════════════════════════════
// Sales Order — List View Client Script
// Combined: Group By + Left ID Inject + Business Status
