frappe.listview_settings["Sales Order"] = {
  add_fields: ["name", "transaction_date", "customer", "custom_payment_status", "per_billed", "docstatus"],

  get_indicator(doc) {
    const status = get_so_business_status(doc);
    const status_map = {
      "Draft":          ["Draft",          "grey"],
      "To Invoice":     ["To Invoice",     "light-blue"],
      "Fully Invoiced": ["Fully Invoiced", "green"],
      "Cancelled":      ["Cancelled",      "red"],
    };
    return status_map[status] || [status, "grey"];
  },

  formatters: {
    custom_payment_status(value, df, doc) {
      const status = get_so_business_status(doc);
      const color = get_so_status_color(status);
      const icon_map = {};
      return `<span class="indicator-pill ${color} ellipsis">${icon_map[status] || ""} ${frappe.utils.escape_html(status)}</span>`;
    }
  },

  onload(listview) {
    const DATE_FIELD    = "transaction_date";
    const ANCHOR_FIELD  = "customer";
    const GROUP_OPTIONS = ["Year", "Quarter", "Month", "Week", "Day"];

    let selected_groups  = [];
    let collapsed_groups = {};
    let apply_timer      = null;
    let is_rendering     = false;

    // ── Inject CSS ──────────────────────────────────────────
    if (!document.getElementById("so-combined-style")) {
      const s = document.createElement("style");
