        ".erg-dd-btn{flex:1;border:1px solid #d1d8dd;background:#fff;color:#36414c;font-size:11px;border-radius:6px;padding:6px 8px;cursor:pointer}" +
        ".erg-dd-btn.primary{background:#2490ef;color:#fff;border-color:#2490ef}" +
        ".erg-dd-btn:hover{background:#f5f7fa}" +
        ".erg-dd-btn.primary:hover{background:#1a7fd4}" +

        // Group headers
        ".erg-group-separator{margin:20px 0 8px;border-top:2px solid #dbe3ea}" +
        ".erg-group-header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;margin:0 0 6px;background:#f7f9fb;border:1px solid #e3e8ee;border-radius:8px;cursor:pointer;user-select:none}" +
        ".erg-group-header:hover{background:#f2f6fa}" +
        ".erg-group-left{display:flex;align-items:center;gap:10px;min-width:0}" +
        ".erg-group-toggle{width:18px;text-align:center;color:#8d99a6;font-size:12px;flex:0 0 auto}" +
        ".erg-group-title{font-size:12px;font-weight:700;color:#36414c;line-height:1.3}" +
        ".erg-group-sub{font-size:11px;color:#8d99a6;line-height:1.3;margin-top:2px}" +
        ".erg-group-right{display:flex;align-items:center;gap:8px;flex-shrink:0}" +
        ".erg-group-count{font-size:11px;color:#68717d;background:#edf2f7;border:1px solid #dde5ee;border-radius:999px;padding:2px 8px;white-space:nowrap}" +
        ".erg-group-badge{flex:0 0 auto;font-size:10px;font-weight:600;color:#68717d;background:#edf2f7;border:1px solid #dde5ee;border-radius:999px;padding:3px 8px}" +
        ".erg-lvl-1{margin-top:10px}" +
        ".erg-lvl-2{margin-left:18px;background:#fbfcfd}" +
        ".erg-lvl-3{margin-left:36px;background:#fcfdfe}" +
        ".erg-lvl-4{margin-left:54px;background:#fff}" +
        ".erg-lvl-5{margin-left:72px;background:#fff}" +
        ".erg-hidden-by-collapse{display:none!important}" +

        // Left ID layout
        ".list-row .list-subject.level,.list-row-head .list-subject.level{min-width:340px!important;width:340px!important}" +
        ".list-row .list-subject.level{display:flex!important;align-items:center!important;min-height:44px!important}" +
        ".list-row-head .list-subject.level{display:flex!important;align-items:center!important;min-height:40px!important}" +
        ".list-row .list-subject.level .level-item.select-like{flex:0 0 28px!important;margin-right:0!important}" +
        ".list-row-head .list-subject.level .level-item.select-like{flex:0 0 28px!important;margin-right:0!important}" +
        ".so-customer-name{flex:0 0 110px!important;width:110px!important;overflow:hidden!important;text-overflow:ellipsis!important;white-space:nowrap!important;font-size:13px!important;font-weight:400!important;color:#36414c!important}" +
        ".so-customer-name a{color:#36414c!important;font-weight:400!important;text-decoration:none!important;font-size:13px!important}" +
        ".so-id-inject{flex:1 1 0!important;overflow:hidden!important;text-overflow:ellipsis!important;white-space:nowrap!important;padding-left:8px!important}" +
        ".so-id-inject a{font-weight:400!important;color:#36414c!important;font-size:13px!important;text-decoration:none!important}" +
        ".so-hidden-id-col{display:none!important}" +
        ".so-hidden-outstanding-col{display:none!important}";
      document.head.appendChild(s);
    }

    // ── Helpers ─────────────────────────────────────────────
    const MN = ["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"];

    function pd(s)    { return s ? frappe.datetime.str_to_obj(s) : null; }
    function wom(d)   { const f = new Date(d.getFullYear(), d.getMonth(), 1); return Math.ceil((d.getDate() + f.getDay()) / 7); }
    function esc(t)   { return frappe.utils.escape_html(t == null ? "" : String(t)); }

    function gv(d, mode) {
      if (!d) return { key: "NO_DATE", label: "No Date" };
      const y = d.getFullYear(), m = d.getMonth(), day = d.getDate(),
            q = Math.floor(m / 3) + 1, w = wom(d);
      if (mode === "Year")    return { key: `${y}`,                                              label: `${y}` };
      if (mode === "Quarter") return { key: `${y}-Q${q}`,                                        label: `Q${q} ${y}` };
      if (mode === "Month")   return { key: `${y}-${String(m+1).padStart(2,"0")}`,               label: `${MN[m]} ${y}` };
      if (mode === "Week")    return { key: `${y}-${String(m+1).padStart(2,"0")}-W${w}`,         label: `Minggu ${w} - ${MN[m]} ${y}` };
      if (mode === "Day")     return { key: `${y}-${String(m+1).padStart(2,"0")}-${String(day).padStart(2,"0")}`, label: `${String(day).padStart(2,"0")} ${MN[m]} ${y}` };
      return { key: "X", label: "Unknown" };
    }

    function getRows() {
      return listview.$result
        ? listview.$result.find(".list-row-container").filter(function() { return !!getDN($(this)); })
        : $();
    }
    function getDN($r) { return $r.attr("data-name") || $r.find("[data-name]").first().attr("data-name") || null; }
    function getDoc(n) { return Array.isArray(listview.data) ? listview.data.find(d => d.name === n) || null : null; }

    // ── Group By Logic ───────────────────────────────────────
    function rmv() {
      if (!listview.$result) return;
      listview.$result.find(".erg-group-header,.erg-group-separator").remove();
      listview.$result.find(".erg-hidden-by-collapse").removeClass("erg-hidden-by-collapse");
    }

    function mkSep() { return $('<div class="erg-group-separator">'); }

    function mkHdr(lv, mode, label, sub, ck, count) {
      const ic = !!collapsed_groups[ck];
      const countLabel = count === 1 ? "1 transaksi" : count + " transaksi";
      return $(
        `<div class="erg-group-header erg-lvl-${lv}" data-group-level="${lv}" data-chain-key="${esc(ck)}" data-collapsed="${ic ? "1" : "0"}">` +
          `<div class="erg-group-left">` +
            `<div class="erg-group-toggle">${ic ? "&#9658;" : "&#9660;"}</div>` +
            `<div class="erg-group-text">` +
              `<div class="erg-group-title">${esc(label)}</div>` +
              `<div class="erg-group-sub">${esc(sub || "")}</div>` +
            `</div>` +
          `</div>` +
          `<div class="erg-group-right">` +
            `<div class="erg-group-count">${esc(countLabel)}</div>` +
            `<div class="erg-group-badge">${esc(mode)}</div>` +
          `</div>` +
        `</div>`
      );
    }

    function doCollapse($h) {
      const lv = parseInt($h.attr("data-group-level"), 10);
      collapsed_groups[$h.attr("data-chain-key")] = true;
      $h.attr("data-collapsed", "1").find(".erg-group-toggle").html("&#9658;");
      let $n = $h.next();
      while ($n.length) {
        if ($n.hasClass("erg-group-header") && parseInt($n.attr("data-group-level"), 10) <= lv) break;
        $n.addClass("erg-hidden-by-collapse"); $n = $n.next();
      }
    }

    function doExpand($h) {
      const lv = parseInt($h.attr("data-group-level"), 10);
      delete collapsed_groups[$h.attr("data-chain-key")];
      $h.attr("data-collapsed", "0").find(".erg-group-toggle").html("&#9660;");
      let $n = $h.next();
      while ($n.length) {
        if ($n.hasClass("erg-group-header")) {
          const nl = parseInt($n.attr("data-group-level"), 10);
          if (nl <= lv) break;
          $n.removeClass("erg-hidden-by-collapse");
          if ($n.attr("data-collapsed") === "1") {
            let $s = $n.next();
            while ($s.length) {
              if ($s.hasClass("erg-group-header") && parseInt($s.attr("data-group-level"), 10) <= nl) break;
              $s.addClass("erg-hidden-by-collapse"); $s = $s.next();
            }
          }
        } else {
          $n.removeClass("erg-hidden-by-collapse");
        }
        $n = $n.next();
      }
      listview.$result.find(".erg-group-header[data-collapsed='1']").each(function() { doCollapse($(this)); });
    }

    function bindEv() {
      listview.$result.find(".erg-group-header").off("click.erg").on("click.erg", function(e) {
        e.stopPropagation();
        $(this).attr("data-collapsed") === "1" ? doExpand($(this)) : doCollapse($(this));
      });
    }

    function applyGrouping() {
      if (is_rendering || !listview.$result) return;
      if (!selected_groups.length) { rmv(); return; }
      is_rendering = true;
      try {
        rmv();
        const rs = [];
        getRows().each(function() {
          const $r = $(this), n = getDN($r);
          if (!n) return;
          const d = getDoc(n), dObj = pd(d ? d[DATE_FIELD] : null);
          rs.push({ $r, n, dObj, ts: dObj ? dObj.getTime() : 0 });
        });
        rs.sort((a, b) => a.ts !== b.ts ? a.ts - b.ts : a.n.localeCompare(b.n));
        if (rs.length) { const $p = rs[0].$r.parent(); rs.forEach(r => $p.append(r.$r)); }

        const countMap = {};
        rs.forEach(item => {
          const chain = selected_groups.map(mode => { const g = gv(item.dObj, mode); return { mode, key: String(g.key), label: g.label }; });
          chain.forEach((g, idx) => {
            const ck = chain.slice(0, idx + 1).map(x => x.mode + ":" + x.key).join("||");
            countMap[ck] = (countMap[ck] || 0) + 1;
          });
        });

        let pk = [], pt = null;
        rs.forEach(item => {
          const chain = selected_groups.map(mode => { const g = gv(item.dObj, mode); return { mode, key: String(g.key), label: g.label }; });
          if (!chain.length) return;
          const tk = chain[0].mode + ":" + chain[0].key;
          chain.forEach((g, idx) => {
            const lv = idx + 1;
            const ck = chain.slice(0, lv).map(x => x.mode + ":" + x.key).join("||");
            if (pk[idx] !== ck) {
              if (idx === 0 && pt !== null && tk !== pt) item.$r.before(mkSep());
              const sub = idx === 0 ? "Group by " + g.mode : chain.slice(0, idx).map(x => x.label).join(" / ");
              item.$r.before(mkHdr(lv, g.mode, g.label, sub, ck, countMap[ck] || 0));
              pk[idx] = ck;
              for (let j = idx + 1; j < pk.length; j++) pk[j] = null;
            }
          });
          pt = tk;
        });

        bindEv();
        if (!Object.keys(collapsed_groups).length) {
          listview.$result.find(".erg-group-header").each(function() { doCollapse($(this)); });
        } else {
          listview.$result.find(".erg-group-header[data-collapsed='1']").each(function() { doCollapse($(this)); });
        }
      } finally { is_rendering = false; }
    }

    // ── Left ID Inject ───────────────────────────────────────
    function render_left_id() {
      return; // so-no-inject: name is the subject column now
      if (!listview.$result) return;

      listview.$result.find(".list-row .list-subject.level").each(function() {
        const $subject = $(this);
        const $row = $subject.closest(".list-row-container");
        const docname = $row.attr("data-name") || $subject.find("a[data-name]").first().attr("data-name");
        if (!docname) return;
        if ($subject.find(".so-id-inject").length) return;

        $subject.children("span").not(".level-item.select-like").each(function() {
          $(this).addClass("so-customer-name");
        });

        const href = `/app/sales-order/${encodeURIComponent(docname)}`;
        $subject.append(
          `<span class="so-id-inject">` +
            `<a href="${href}" data-name="${esc(docname)}" title="${esc(docname)}">${esc(docname)}</a>` +
          `</span>`
        );
      });

      // Hide kolom ID kanan
      listview.$result.find(".list-row").each(function() {
        $(this).find(".list-row-col").each(function() {
          const $col = $(this);
          if ($col.find("a.filterable[data-filter^='name,=,']").length && !$col.hasClass("list-subject")) {
            $col.addClass("so-hidden-id-col");
          }
        });
      });

      // Hide header kolom ID kanan
      listview.$result.find(".list-row-head .list-row-col").each(function() {
        const $col = $(this);
        if ($col.text().trim() === "ID" && !$col.hasClass("list-subject")) {
          $col.addClass("so-hidden-id-col");
        }
      });

      // Hide kolom Outstanding Amount
      listview.$result.find(".list-row, .list-row-head").each(function() {
        $(this).find(".list-row-col").each(function() {
          const $col = $(this);
          if ($col.attr("data-fieldname") === "outstanding_amount" || $col.text().trim().startsWith("Outstanding")) {
            $col.addClass("so-hidden-outstanding-col");
          }
        });
      });

      // Header subject kiri
      const $subjectHead = listview.$result.find(".list-row-head .list-subject.level");
      if ($subjectHead.length) {
        $subjectHead.find(".so-id-head-inject").remove();
        $subjectHead.find("span:not(.level-item.select-like)").remove();
        $subjectHead.append(
          `<span class="so-customer-name so-id-head-inject" style="font-size:13px;font-weight:400;color:#36414c;">Customer Name</span>` +
          `<span class="so-id-inject so-id-head-inject" style="font-size:13px;font-weight:400;color:#36414c;padding-left:8px;">ID</span>`
        );
      }
    }

    // ── Scheduler ────────────────────────────────────────────
    function sched(d) {
      clearTimeout(apply_timer);
      apply_timer = setTimeout(() => { applyGrouping(); render_left_id(); }, d || 400);
    }

    // ── Group By UI ──────────────────────────────────────────
    function updDisp() {
      if (selected_groups.length) {
        $("#erg-text").text(selected_groups.join(" + ")).removeClass("is-placeholder");
        $("#erg-clr").show();
      } else {
        $("#erg-text").text("Group By").addClass("is-placeholder");
        $("#erg-clr").hide();
      }
    }

    function syncChk() {
      $("#erg-dd .erg-opt-check").each(function() {
        $(this).prop("checked", selected_groups.indexOf($(this).val()) > -1);
      });
    }

    function buildUI() {
      const opts = GROUP_OPTIONS.map(o =>
        `<label class="erg-opt"><input type="checkbox" class="erg-opt-check" value="${o}"><span>${o}</span></label>`
      ).join("");
      return $(
        `<div id="erg-wrap">` +
          `<div id="erg-select"><span id="erg-text" class="is-placeholder">Group By</span></div>` +
          `<div id="erg-chevron"><svg class="icon icon-xs" aria-hidden="true"><use href="#icon-select"></use></svg></div>` +
          `<span id="erg-clr">&times;</span>` +
          `<div id="erg-dd">` +
            `<div class="erg-dd-title">Pilih level grouping</div>` +
            opts +
            `<div class="erg-dd-actions">` +
              `<button class="erg-dd-btn" id="erg-sa">All</button>` +
              `<button class="erg-dd-btn" id="erg-ca">Clear</button>` +
              `<button class="erg-dd-btn primary" id="erg-ap">Apply</button>` +
            `</div>` +
          `</div>` +
        `</div>`
      );
    }

    function attachUI($w) {
      $w.on("click", "#erg-select", function(e) { e.stopPropagation(); syncChk(); $("#erg-dd").toggle(); });
      $w.on("click", "#erg-sa",     function(e) { e.stopPropagation(); $("#erg-dd .erg-opt-check").prop("checked", true); });
      $w.on("click", "#erg-ca",     function(e) { e.stopPropagation(); $("#erg-dd .erg-opt-check").prop("checked", false); });
      $w.on("click", "#erg-ap", function(e) {
        e.stopPropagation();
        selected_groups  = GROUP_OPTIONS.filter(o => $("#erg-dd .erg-opt-check[value='" + o + "']").prop("checked"));
        collapsed_groups = {};
        updDisp(); $("#erg-dd").hide(); sched(300);
      });
      $w.on("click", "#erg-clr", function(e) {
        e.stopPropagation();
        selected_groups = []; collapsed_groups = {};
        updDisp(); rmv(); render_left_id(); syncChk();
      });
      $(document).off("click.erg").on("click.erg", function() { $("#erg-dd").hide(); });
      $w.on("click", "#erg-dd", function(e) { e.stopPropagation(); });
    }

    function injectUI() {
      $("#erg-wrap").remove();
      const $a = $(`[data-fieldname="${ANCHOR_FIELD}"].frappe-control`);
      if (!$a.length) return false;
      const $w = buildUI(); $a.after($w); attachUI($w); updDisp(); return true;
    }

    // ── Patch listview render ─────────────────────────────────
    if (!listview.__erg_patched) {
      listview.__erg_patched = true;
      const oR = listview.render, oRf = listview.refresh;
      listview.render  = function() { const r = oR.apply(this, arguments);  sched(500); return r; };
      listview.refresh = function() { const r = oRf.apply(this, arguments); sched(600); return r; };
    }

    frappe.after_ajax(function() {
      if (!injectUI()) {
        let n = 0;
        const iv = setInterval(function() { n++; if (injectUI() || n > 20) clearInterval(iv); }, 200);
      }
      sched(700);
    });
  }
};

