frappe.ui.form.on('Sales Order', {
  setup(frm) {
    frm.set_query('custom_otobitz_vehicle', () => ({
      query: 'otobitz_integration.otobitz_integration.doctype.otobitz_vehicle.otobitz_vehicle.search_vehicle',
      filters: {}
    }));
  },
  refresh(frm) {
    frm.set_query('uom','items',()=>({filters:{name:['in',['Units','Dozen']]}}));
    $(frm.wrapper).addClass('so-hz'); $(document.body).addClass('full-width');
    if (frm.is_new() && !frm.doc.custom_next_service_date) {
      frm.set_value('custom_next_service_date', frappe.datetime.add_months(frappe.datetime.get_today(), 1));
    }
  },
  custom_otobitz_vehicle(frm) {
    const f = ['custom_nomor_rangka','custom_nomor_mesin','custom_tahun_kendaraan','custom_vehicle_type','custom_warna'];
    if (!frm.doc.custom_otobitz_vehicle) { f.forEach(k => frm.set_value(k, '')); return; }
    frappe.db.get_value('OtoBitz Vehicle', frm.doc.custom_otobitz_vehicle,
      ['norangka','nomesin','tahunpembuatan','vehicle_type','vehicle_color','last_odometer','customer'], r => {
        if (!r) return;
        frm.set_value('custom_nomor_rangka', r.norangka || '');
        frm.set_value('custom_nomor_mesin', r.nomesin || '');
        frm.set_value('custom_tahun_kendaraan', r.tahunpembuatan || '');
        frm.set_value('custom_vehicle_type', r.vehicle_type || '');
        frm.set_value('custom_warna', r.vehicle_color || '');
        if (r.last_odometer) frm.set_value('custom_odometer', r.last_odometer);
        if (r.customer) frm.set_value('customer', r.customer);
        if (r.vehicle_type) frappe.db.get_value('OtoBitz Vehicle Type', r.vehicle_type, ['brand','transmisi','custom_model'], t => { frm.set_value('custom_vehicle_manufacture', (t && t.brand) || ''); frm.set_value('custom_transmisi', (t && t.transmisi) || ''); frm.set_value('custom_vehicle_model', (t && t.custom_model) || ''); });
      });
  }
});

