function so_render_totals(frm) {
  const f = frm.fields_dict.custom_totals_html;
  if (!f) return;
  const d = frm.doc, cur = d.currency;
  const fmt = v => format_currency(flt(v), cur);
  const tax = (d.taxes || [])[0];
  const lbl = tax ? 'PPN ' + (flt(tax.rate) % 1 ? flt(tax.rate, 2) : parseInt(tax.rate)) + '%' : 'PPN';
  const key = [d.net_total, d.total_taxes_and_charges, d.grand_total, lbl].join('|');
  if (frm._so_tot_key === key) return;
  frm._so_tot_key = key;
  f.$wrapper.html(`<div class="so-tot">
    <div class="so-tot-row"><span>Total (DPP)</span><b>${fmt(d.net_total)}</b></div>
    <div class="so-tot-row"><span>${lbl}</span><b>${fmt(d.total_taxes_and_charges)}</b></div>
    <div class="so-tot-row grand"><span>Grand Total</span><b>${fmt(d.grand_total)}</b></div></div>`);
}
frappe.ui.form.on('Sales Order', {
  refresh(frm) {
    frm._so_tot_key = null; so_render_totals(frm);
    // ponytail: poll because ERPNext sets totals without firing field events; replace with a calculate_taxes_and_totals hook if it gets heavy
    clearInterval(frm._so_tot_t);
    frm._so_tot_t = setInterval(() => { if (cur_frm !== frm) return clearInterval(frm._so_tot_t); so_render_totals(frm); }, 400);
  }
});



/* so-defaults */
// ponytail: tax template name hardcoded for the single company; make it a setting if more companies appear
const SO_INC_TAX = '(Inc) Pajak Pertambahan Nilai - PAO';
function so_row_defaults(frm) {
  const dd = frm.doc.delivery_date || frappe.datetime.get_today();
  (frm.doc.items || []).forEach(r => { if (!r.delivery_date) r.delivery_date = dd; });
}
frappe.ui.form.on('Sales Order', {
  validate(frm) { so_row_defaults(frm); }
});
frappe.ui.form.on('Sales Order Item', {
  items_add(frm, cdt, cdn) { const r = locals[cdt][cdn]; if (!r.delivery_date) frappe.model.set_value(cdt, cdn, 'delivery_date', frm.doc.delivery_date || frappe.datetime.get_today()); },
  item_code(frm, cdt, cdn) {
    frappe.after_ajax(() => {
      const r = locals[cdt][cdn];
      if (r && r.item_code && !r.item_tax_template) frappe.model.set_value(cdt, cdn, 'item_tax_template', SO_INC_TAX);
      if (r && !r.delivery_date) frappe.model.set_value(cdt, cdn, 'delivery_date', frm.doc.delivery_date || frappe.datetime.get_today());
    });
  }
});

/* hide-side */
// ponytail: Odoo has no sidebar; saved docs show it and squeeze grid. Re-enable by deleting this block.
frappe.ui.form.on('Sales Order', {
  refresh(frm) {
    frm.page.wrapper.find('.layout-side-section').hide();
    frm.page.wrapper.find('.layout-main-section-wrapper').css({'width': '100%', 'max-width': '100%', 'flex': '0 0 100%'});
  }
});

frappe.ui.form.on("Sales Order", {
  onload(frm) {
    if (!frm.is_new()) return;
    if (!frm.doc.custom_salesperson) frm.set_value("custom_salesperson", frappe.session.user);
    if (!frm.doc.custom_effective_date) frm.set_value("custom_effective_date", frappe.datetime.now_datetime());
  },
  // ponytail: erpnext.hide_company (transaction.js refresh) hides Company with one company; re-show after it runs
  refresh(frm) { setTimeout(() => frm.toggle_display("company", true), 300); },
  custom_salesperson(frm) {
    if (!frm.doc.custom_salesperson) { frm.set_value({custom_oi_employee: "", custom_oi_department: ""}); return; }
    frappe.db.get_value("Employee", {user_id: frm.doc.custom_salesperson}, ["name", "department"]).then(r => {
      const v = r.message || {};
      frm.set_value({custom_oi_employee: v.name || "", custom_oi_department: v.department || ""});
    });
  },
  custom_oi_employee(frm) {
    if (!frm.doc.custom_oi_employee) return;
    frappe.db.get_value("Employee", frm.doc.custom_oi_employee, "department").then(r => frm.set_value("custom_oi_department", (r.message || {}).department || ""));
  }
});


/* so-nodo-msg */
// ponytail: imogi_finance's towing hook warns on every SO submit; Otobitz SO has no towing table.
// Drop only that message. Remove this block if imogi_finance gets a setting to skip it.
if (!frappe._so_nodo_patched) {
  frappe._so_nodo_patched = true;
  const _mp = frappe.msgprint;
  frappe.msgprint = function (m, ...rest) {
    const t = typeof m === 'string' ? m : (m && m.message) || '';
    if (typeof t === 'string' && t.includes('DO tidak dibuat')) return;
    return _mp.call(this, m, ...rest);
  };
}


/* so-create-inv */
// Odoo-style shortcut: one click opens a pre-filled Sales Invoice (standard mapper copies same-named custom fields)
frappe.ui.form.on('Sales Order', {
  refresh(frm) {
    if (frm.doc.docstatus !== 1 || flt(frm.doc.per_billed) >= 100) return;
    frm.add_custom_button(__('Create Invoice'), () => frappe.model.open_mapped_doc({
      method: 'erpnext.selling.doctype.sales_order.sales_order.make_sales_invoice',
      frm: frm
    })).addClass('btn-primary');
  }
});
